 "content": "from collections import deque

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            yield color, cells

def _shape(cells):
    minr = min(r for r, c in cells)
    minc = min(c for r, c in cells)
    return frozenset((r-minr, c-minc) for r, c in cells)

def transform(grid):
    out = [row[:] for row in grid]
    comps = list(_components(grid))
    exemplars = {}
    for color, cells in comps:
        if color != 1:
            exemplars.setdefault(_shape(cells), color)
    for color, cells in comps:
        if color == 1:
            new_color = exemplars.get(_shape(cells))
            if new_color is not None:
                for r, c in cells:
                    out[r][c] = new_color
    return out
